#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
#include <cstdint>
#include <functional>

class Solution {
public:
    int countBalanced(int low, int high) {
        if (high < 11) return 0;
        low = std::max(low, 11);

        std::string low_str = std::to_string(low);
        std::string high_str = std::to_string(high);
        std::vector<int> low_s, high_s;
        low_s.reserve(low_str.size());
        high_s.reserve(high_str.size());
        for (char c : low_str) low_s.push_back(c - '0');
        for (char c : high_str) high_s.push_back(c - '0');

        int n = static_cast<int>(high_s.size());
        int diff_lh = n - static_cast<int>(low_s.size());

        struct Key {
            int i;
            int diff;
            bool limit_low;
            bool limit_high;
            bool operator==(const Key& other) const {
                return i == other.i && diff == other.diff &&
                       limit_low == other.limit_low && limit_high == other.limit_high;
            }
        };

        struct KeyHasher {
            std::size_t operator()(const Key& k) const noexcept {
                std::size_t h = std::hash<int>()(k.i);
                h ^= std::hash<int>()(k.diff) + 0x9e3779b9 + (h << 6) + (h >> 2);
                h ^= std::hash<bool>()(k.limit_low) + 0x9e3779b9 + (h << 6) + (h >> 2);
                h ^= std::hash<bool>()(k.limit_high) + 0x9e3779b9 + (h << 6) + (h >> 2);
                return h;
            }
        };

        std::unordered_map<Key, long long, KeyHasher> memo;

        std::function<long long(int, int, bool, bool)> dfs = [&](int i, int diff, bool limit_low, bool limit_high) -> long long {
            if (i == n) return diff == 0 ? 1LL : 0LL;

            Key key{i, diff, limit_low, limit_high};
            auto it = memo.find(key);
            if (it != memo.end()) return it->second;

            int lo = 0;
            if (limit_low && i >= diff_lh) lo = low_s[i - diff_lh];
            int hi = limit_high ? high_s[i] : 9;

            long long res = 0;
            int start = lo;

            if (limit_low && i < diff_lh) {
                res += dfs(i + 1, diff, true, false);
                start = 1;
            }

            for (int d = start; d <= hi; ++d) {
                int new_diff = diff + (i % 2 ? d : -d);
                bool new_limit_low = limit_low && (d == lo);
                bool new_limit_high = limit_high && (d == hi);
                res += dfs(i + 1, new_diff, new_limit_low, new_limit_high);
            }

            memo[key] = res;
            return res;
        };

        return static_cast<int>(dfs(0, 0, true, true));
    }
};

