// Helper function to compute balanced numbers by brute force
bool isBalanced(int n) {
    std::string s = std::to_string(n);
    int diff = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        int d = s[i] - '0';
        if (i % 2 == 0) diff -= d;
        else diff += d;
    }
    return diff == 0;
}

int bruteCount(int low, int high) {
    int count = 0;
    for (int i = low; i <= high; ++i) {
        if (isBalanced(i)) ++count;
    }
    return count;
